using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AmbushCustomEventSetup", menuName = "Data/BattleSceneSetups/Events/AmbushCustomEventSetup", order = 0)]
public class AmbushCustomEventSetup : CustomEventSetup
{
	[Header("Battle Setup")]
	[SerializeField]
	private BattleSetup battleSetup;

	[SerializeField]
	private ClearingReward ambushBattleReward;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private NodeEnum nodeEnum;

	public NodeEnum NodeEnum => nodeEnum;

	public override void SetupScene()
	{
		mapHandler.SetClearingReward(ambushBattleReward, goToEndOfBattleState: false);
		mapHandler.SetBattleSceneSetupToBattle();
		battleSetup.InstantiateAmbushBattleScene();
	}
}
